class Solution:
    def numIslands(self, grid):
        seen = set()
        def visit(r, c):
            if r < 0 or r == len(grid) or c < 0 or c == len(grid[0]) or grid[r][c] == '0' or (r, c) in seen: return
            seen.add((r, c)); visit(r+1,c); visit(r-1,c); visit(r,c+1); visit(r,c-1)
        count = 0
        for r in range(len(grid)):
            for c in range(len(grid[0]) if grid else 0):
                if grid[r][c] == '1' and (r,c) not in seen: count += 1; visit(r,c)
        return count
